using System.Reflection;
if(args.Length!=6 || args[0]!="--testClass" || args[1]!="ArcadeRoundLayoutRuntimeChecks" || args[2]!="--maxTests" || int.Parse(args[3])<3 || args[4]!="--includePassingTests" || args[5]!="true")throw new ArgumentException("Declare testClass ArcadeRoundLayoutRuntimeChecks, maxTests >= 3, includePassingTests true");
